"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/data-table/variants/01-responsive";
import Variant1 from "./components/data-table/variants/02-default";
import Variant2 from "./components/data-table/variants/03-pagination";
const variants = { responsive: Variant0, default: Variant1, pagination: Variant2 };
export interface ArtemisDataTableProps {
  className?: string;
  variant?: "responsive" | "default" | "pagination";
}
export function ArtemisDataTable({ className, variant = "responsive" }: ArtemisDataTableProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { Fragment, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type PointerEvent as ReactPointerEvent } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { desktopRow, mobileCard } from "./01-responsive/rows";
import { FilterMenu } from "./01-responsive/filter-menu";
const accounts = [
    { name: "Assistant team", email: "taylor@example.com", channel: "Direct", status: "Active", plan: "Enterprise", seats: 105, mrr: 15800, renewal: "Nov 19" },
    { name: "Design team", email: "alex@example.com", channel: "Direct", status: "Active", plan: "Enterprise", seats: 84, mrr: 12400, renewal: "Sep 24" },
    { name: "Finance team", email: "quinn@example.com", channel: "Partner", status: "Trial", plan: "Enterprise", seats: 61, mrr: 9100, renewal: "Nov 08" },
    { name: "Engineering team", email: "cameron@example.com", channel: "Product-led", status: "Active", plan: "Scale", seats: 46, mrr: 7200, renewal: "Oct 11" },
    { name: "Support team", email: "robin@example.com", channel: "Partner", status: "Active", plan: "Scale", seats: 38, mrr: 5900, renewal: "Dec 12" },
    { name: "Workspace Labs", email: "morgan@example.com", channel: "Partner", status: "Trial", plan: "Scale", seats: 32, mrr: 4800, renewal: "Oct 02" },
    { name: "Research team", email: "riley@example.com", channel: "Product-led", status: "Active", plan: "Scale", seats: 29, mrr: 3650, renewal: "Nov 01" },
    { name: "Member team", email: "jordan@example.com", channel: "Product-led", status: "Paused", plan: "Starter", seats: 12, mrr: 1200, renewal: "Dec 03" },
    { name: "Operations team", email: "sam@example.com", channel: "Direct", status: "Paused", plan: "Starter", seats: 8, mrr: 890, renewal: "Oct 18" },
] as const;
const sourceOrder = [6, 0, 5, 2, 8, 1, 4, 7, 3];
type FilterKind = "status" | "columns";
type SortField = "name" | "status" | "plan" | "seats" | "mrr";
function SortGlyph({ active, direction }: {
    active: boolean;
    direction: "asc" | "desc";
}) {
    return active ? <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-${direction === "asc" ? "art:up" : "art:down"} art:size-3.5`} aria-hidden="true"><path d={direction === "asc" ? "m18 15-6-6-6 6" : "m6 9 6 6 6-6"}/></svg> : <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevrons-up-down art:size-3.5 art:opacity-45" aria-hidden="true"><path d="m7 15 5 5 5-5"/><path d="m7 9 5-5 5 5"/></svg>;
}
export default function DataTableResponsive() {
    const reduceMotion = useReducedMotion();
    const [tab, setTab] = useState("All accounts");
    const [search, setSearch] = useState("");
    const [statuses, setStatuses] = useState<string[]>(["Active", "Trial", "Paused"]);
    const [columns, setColumns] = useState<string[]>(["Account", "Status", "Plan", "Seats", "MRR", "Renewal"]);
    const [sort, setSort] = useState<{
        field: SortField;
        direction: "asc" | "desc";
    }>({ field: "mrr", direction: "desc" });
    const [showAllMobile, setShowAllMobile] = useState(false);
    const [isMobile, setIsMobile] = useState(false);
    const [openMenu, setOpenMenu] = useState<FilterKind | null>(null);
    const [keyboardMenu, setKeyboardMenu] = useState(false);
    const menuBase = `radix-${useId()}`;
    const statusTriggerId = `${menuBase}-status-trigger`;
    const columnsTriggerId = `${menuBase}-columns-trigger`;
    const statusContentId = `${menuBase}-status-content`;
    const columnsContentId = `${menuBase}-columns-content`;
    const statusTrigger = useRef<HTMLButtonElement>(null);
    const columnsTrigger = useRef<HTMLButtonElement>(null);
    useEffect(() => {
        const media = matchMedia("(max-width: 767px)");
        const update = () => setIsMobile(media.matches);
        update();
        media.addEventListener("change", update);
        return () => media.removeEventListener("change", update);
    }, []);
    const onTriggerPointerDown = (event: ReactPointerEvent<HTMLButtonElement>, kind: FilterKind) => {
        if (event.button !== 0 || event.ctrlKey)
            return;
        event.preventDefault();
        event.currentTarget.removeAttribute("data-artemis-pointer-focus");
        setKeyboardMenu(false);
        setOpenMenu(current => current === kind ? null : kind);
    };
    const onTriggerKeyDown = (event: ReactKeyboardEvent<HTMLButtonElement>, kind: FilterKind) => {
        event.currentTarget.removeAttribute("data-artemis-pointer-focus");
        if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            setKeyboardMenu(true);
            setOpenMenu(current => current === kind ? null : kind);
        }
        else if (event.key === "ArrowDown") {
            event.preventDefault();
            setKeyboardMenu(true);
            setOpenMenu(kind);
        }
    };
    const visible = useMemo(() => accounts.map((_, index) => index).filter(index => {
        const account = accounts[index];
        const term = search.trim().toLowerCase();
        return (tab === "All accounts" || account.channel === tab) && statuses.includes(account.status) && (!term || `${account.name} ${account.email} ${account.plan}`.toLowerCase().includes(term));
    }).sort((left, right) => {
        const a = accounts[left][sort.field];
        const b = accounts[right][sort.field];
        const result = typeof a === "number" && typeof b === "number" ? a - b : String(a).localeCompare(String(b));
        return (sort.direction === "asc" ? result : -result) || sourceOrder[left] - sourceOrder[right];
    }), [tab, search, statuses, sort]);
    const sortedColumn = { name: "Account", status: "Status", plan: "Plan", seats: "Seats", mrr: "MRR" }[sort.field];
    const desktopVisible = columns.includes(sortedColumn) ? visible : [...visible].sort((left, right) => sourceOrder[left] - sourceOrder[right]);
    const changeSort = (field: SortField) => setSort(previous => ({ field, direction: previous.field === field && previous.direction === "asc" ? "desc" : "asc" }));
    const resultCount = visible.length;
    return (<>
      <div className="art:w-full art:p-2 art:@min-[640px]/artemis:p-5">
        <section className="art:w-full art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
          <header className="art:border-border art:border-b art:px-3 art:pt-3 art:pb-3 art:@min-[640px]/artemis:px-4 art:@min-[640px]/artemis:pt-4">
            <div className="art:flex art:flex-col art:gap-3 art:@min-[1024px]/artemis:flex-row art:@min-[1024px]/artemis:items-center art:@min-[1024px]/artemis:justify-between">
              <div className="art:-mx-3 art:overflow-x-auto art:px-3 art:@min-[640px]/artemis:-mx-4 art:@min-[640px]/artemis:px-4 art:@min-[1024px]/artemis:mx-0 art:@min-[1024px]/artemis:px-0">
                <div>
                  <ArtemisSegmentedTabs items={["All accounts", "Direct", "Partner", "Product-led"].map(label => ({ value: label, label }))} value={tab} onValueChange={value => { setTab(value); setShowAllMobile(false); }} layout="position" listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:p-1 art:min-w-max art:border art:border-border art:bg-muted" buttonClassName="art:rounded-full art:min-h-8 art:px-3 art:py-1 art:text-xs art:@min-[640px]/artemis:text-sm"/>
                </div>
              </div>
              <div className="art:flex art:min-w-0 art:flex-1 art:flex-wrap art:items-center art:gap-2 art:@min-[1024px]/artemis:max-w-xl art:@min-[1024px]/artemis:justify-end">
                <label className="art:relative art:min-w-0 art:flex-1 art:@min-[1024px]/artemis:max-w-64">
                  <span className="art:sr-only">
                    {"Search table"}
                  </span>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-search art:pointer-events-none art:absolute art:top-1/2 art:left-3 art:size-4 art:-translate-y-1/2 art:text-muted-foreground" aria-hidden="true">
                    <path d="m21 21-4.34-4.34"/>
                    <circle cx="11" cy="11" r="8"/>
                  </svg>
                  <input placeholder="Search accounts" className="art:h-10 art:w-full art:rounded-full art:border art:border-border art:bg-background art:pr-9 art:pl-9 art:text-sm art:outline-none art:transition-colors art:placeholder:text-muted-foreground art:focus:border-ring art:focus:ring-2 art:focus:ring-ring/20" value={search} onChange={event => { setSearch(event.target.value); setShowAllMobile(false); }}/>
                  {search.length > 0 && <button type="button" aria-label="Clear search" onClick={() => { setSearch(""); setShowAllMobile(false); }} className="art:absolute art:top-1/2 art:right-1.5 art:grid art:size-7 art:-translate-y-1/2 art:place-items-center art:rounded-full art:text-muted-foreground art:transition-colors art:hover:bg-muted art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-3.5" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
                  </button>}
                </label>
                <button ref={statusTrigger} id={statusTriggerId} aria-controls={openMenu === "status" ? statusContentId : undefined} data-radix-popper-side={openMenu === "status" ? "bottom" : undefined} data-radix-popper-align={openMenu === "status" ? "end" : undefined} type="button" aria-haspopup="menu" aria-expanded={openMenu === "status"} data-state={openMenu === "status" ? "open" : "closed"} onPointerDown={event => onTriggerPointerDown(event, "status")} onKeyDown={event => onTriggerKeyDown(event, "status")} onBlur={event => event.currentTarget.removeAttribute("data-artemis-pointer-focus")} className="art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:inline-flex art:h-10 art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background art:px-3 art:font-medium art:text-sm art:transition-colors art:hover:bg-muted/45 art:data-[state=open]:bg-muted/45" aria-label="Filter by Status">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-list-filter art:size-4" aria-hidden="true">
                    <path d="M2 5h20"/>
                    <path d="M6 12h12"/>
                    <path d="M9 19h6"/>
                  </svg>
                  <span className="art:hidden art:@min-[640px]/artemis:inline">
                    {"Status"}
                  </span>
                  {statuses.length !== 3 && <span className="art:grid art:size-5 art:place-items-center art:rounded-full art:bg-primary art:text-primary-foreground art:text-xs art:tabular-nums">{statuses.length}</span>}
                </button>
                <button ref={columnsTrigger} id={columnsTriggerId} aria-controls={openMenu === "columns" ? columnsContentId : undefined} data-radix-popper-side={openMenu === "columns" ? "bottom" : undefined} data-radix-popper-align={openMenu === "columns" ? "end" : undefined} type="button" aria-haspopup="menu" aria-expanded={openMenu === "columns"} data-state={openMenu === "columns" ? "open" : "closed"} onPointerDown={event => onTriggerPointerDown(event, "columns")} onKeyDown={event => onTriggerKeyDown(event, "columns")} onBlur={event => event.currentTarget.removeAttribute("data-artemis-pointer-focus")} className="art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:inline-flex art:h-10 art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background art:px-3 art:font-medium art:text-sm art:transition-colors art:hover:bg-muted/45 art:data-[state=open]:bg-muted/45" aria-label="Choose visible columns">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-columns3 art:lucide-columns-3 art:size-4" aria-hidden="true">
                    <rect width="18" height="18" x="3" y="3" rx="2"/>
                    <path d="M9 3v18"/>
                    <path d="M15 3v18"/>
                  </svg>
                  <span className="art:hidden art:@min-[640px]/artemis:inline">
                    {"Columns"}
                  </span>
                </button>
              </div>
            </div>
          </header>
          <div className="art:hidden art:@min-[768px]/artemis:block">
            <div className="art:w-full art:overflow-hidden art:border-border art:bg-background art:text-sm art:border-0">
              <div className="art:overflow-auto art:[scrollbar-gutter:stable]" style={{ height: `${Math.max(156, Math.min(436, 44 + resultCount * 56))}px` }}>
                <table className="art:min-w-[760px] art:w-full art:table-fixed art:border-collapse">
                  <colgroup>{["Account", "Status", "Plan", "Seats", "MRR", "Renewal"].filter(name => columns.includes(name)).map(name => <col key={name} style={{ width: ({ Account: "30%", Status: "110px", Plan: "120px", Seats: "90px", MRR: "120px", Renewal: "110px" } as Record<string, string>)[name] }}/>)}</colgroup>
                  <thead>
                    <tr>
        {columns.includes("Account") && (<th scope="col" className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs art:text-left">
                        <button type="button" onClick={() => changeSort("name")} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
                          {"Account"}
                          <SortGlyph active={sort.field === "name"} direction={sort.direction}/>
                        </button>
                      </th>)}
        {columns.includes("Status") && (<th scope="col" className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs art:text-left">
                        <button type="button" onClick={() => changeSort("status")} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
                          {"Status"}
                          <SortGlyph active={sort.field === "status"} direction={sort.direction}/>
                        </button>
                      </th>)}
        {columns.includes("Plan") && (<th scope="col" className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs art:text-left">
                        <button type="button" onClick={() => changeSort("plan")} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
                          {"Plan"}
                          <SortGlyph active={sort.field === "plan"} direction={sort.direction}/>
                        </button>
                      </th>)}
        {columns.includes("Seats") && (<th scope="col" className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs art:text-left">
                        <button type="button" onClick={() => changeSort("seats")} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
                          {"Seats"}
                          <SortGlyph active={sort.field === "seats"} direction={sort.direction}/>
                        </button>
                      </th>)}
        {columns.includes("MRR") && (<th scope="col" className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs art:text-right">
                        <button type="button" onClick={() => changeSort("mrr")} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:ml-auto">
                          {"MRR"}
                          <SortGlyph active={sort.field === "mrr"} direction={sort.direction}/>
                        </button>
                      </th>)}
        {columns.includes("Renewal") && (<th scope="col" className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs art:text-right">
                        {"Renewal"}
                      </th>)}
                    </tr>
                  </thead>
                  <tbody>{visible.length ? (isMobile ? [] : desktopVisible.map(index => <Fragment key={index}>{desktopRow(index, columns)}</Fragment>)) : <tr><td colSpan={columns.length} className="art:h-48 art:px-6 art:text-center art:text-muted-foreground">No results match this view.</td></tr>}</tbody>
                </table>
              </div>
            </div>
          </div>
          <div className="art:divide-y art:divide-border art:@min-[768px]/artemis:hidden">
            <AnimatePresence initial={false} mode="popLayout">{visible.slice(0, showAllMobile ? undefined : 8).map(index => mobileCard(index, columns, !!reduceMotion))}</AnimatePresence>
            {!visible.length && <div className="art:px-4 art:py-14 art:text-center art:text-muted-foreground art:text-sm">No results match this view.</div>}
            {!showAllMobile && visible.length > 8 && <div className="art:flex art:justify-center art:bg-background art:p-3"><motion.button whileHover={reduceMotion ? undefined : { scale: 1.01 }} whileTap={reduceMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" onClick={() => setShowAllMobile(true)} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:h-8 art:gap-1.5 art:rounded-full art:px-3 art:text-xs" tabIndex={0}>{"Show"}{" "}{String(visible.length - 8)}{"more"}</motion.button></div>}
          </div>
          <footer className="art:flex art:items-center art:justify-between art:border-border art:border-t art:bg-background art:px-4 art:py-3 art:text-muted-foreground art:text-xs">
            <span className="art:tabular-nums">
              {String(resultCount)}
              {" result"}
              {resultCount === 1 ? " " : "s"}
            </span>
            <span>
              {String(columns.length)}
              {" columns visible"}
            </span>
          </footer>
        </section>
      </div>
      <FilterMenu contentId={statusContentId} keyboardOpen={keyboardMenu} kind="status" open={openMenu === "status"} triggerRef={statusTrigger} selected={statuses} onToggle={name => { setStatuses(previous => previous.includes(name) ? previous.filter(value => value !== name) : [...previous, name]); setShowAllMobile(false); }} onReset={() => { setStatuses(["Active", "Trial", "Paused"]); setShowAllMobile(false); }} onClose={() => setOpenMenu(null)}/>
      <FilterMenu contentId={columnsContentId} keyboardOpen={keyboardMenu} kind="columns" open={openMenu === "columns"} triggerRef={columnsTrigger} selected={columns} onToggle={name => setColumns(previous => previous.includes(name) ? previous.filter(value => value !== name) : [...previous, name])} onClose={() => setOpenMenu(null)}/>
    </>);
}

// @zeus-internal
export { AnimatedBadge } from "../../../../lib/status-badge";
export type { AnimatedBadgeStatus, AnimatedBadgeSize, AnimatedBadgeProps } from "../../../../lib/status-badge";

